import re

def cmp_semver(a: str, b: str) -> int:
    # Strip build metadata (everything after '+')
    a = a.split('+')[0]
    b = b.split('+')[0]

    # Parse into core and optional pre-release
    match_a = re.match(r'^(\d+\.\d+\.\d+)(-.*)?$', a)
    match_b = re.match(r'^(\d+\.\d+\.\d+)(-.*)?$', b)

    if not match_a or not match_b:
        raise ValueError("Invalid SemVer string")

    core_a, pre_a = match_a.group(1), match_a.group(2) or ''
    core_b, pre_b = match_b.group(1), match_b.group(2) or ''

    # Compare major.minor.patch numerically
    parts_a = [int(x) for x in core_a.split('.')]
    parts_b = [int(x) for x in core_b.split('.')]

    for pa, pb in zip(parts_a, parts_b):
        if pa < pb:
            return -1
        if pa > pb:
            return 1

    # If core lengths differ (should not happen with valid semver but handle)
    if len(parts_a) != len(parts_b):
        return -1 if len(parts_a) < len(parts_b) else 1

    # Pre-release handling
    has_pre_a = bool(pre_a)
    has_pre_b = bool(pre_b)

    # A version without pre-release sorts AFTER one with pre-release
    if has_pre_a and not has_pre_b:
        return -1
    if not has_pre_a and has_pre_b:
        return 1

    if has_pre_a and has_pre_b:
        # Split pre-release identifiers by '.'
        pre_ids_a = pre_a.split('.')
        pre_ids_b = pre_b.split('.')

        # Compare identifier by identifier
        for ida, idb in zip(pre_ids_a, pre_ids_b):
            # Determine if each identifier is numeric
            a_num = ida.isdigit()
            b_num = idb.isdigit()

            if a_num and b_num:
                na, nb = int(ida), int(idb)
                if na < nb:
                    return -1
                if na > nb:
                    return 1
            elif a_num and not b_num:
                return -1  # numeric sorts before alphanumeric
            elif not a_num and b_num:
                return 1
            else:
                # Both alphanumeric: compare as strings (case-insensitive)
                if ida.lower() < idb.lower():
                    return -1
                if ida.lower() > idb.lower():
                    return 1

        # All compared identifiers are equal; longer list wins
        if len(pre_ids_a) < len(pre_ids_b):
            return -1
        if len(pre_ids_a) > len(pre_ids_b):
            return 1

    return 0
