def parse_range(header: str, size: int):
    """Parse an RFC 7233 Range header for bytes.

    Returns a list of (start, end) inclusive byte offsets, or None if the header is
    unsatisfiable or malformed.
    """
    # Strip whitespace and handle missing/empty header
    h = header.strip()
    if not h:
        return None

    # Must start with "bytes="
    if not h.lower().startswith("bytes="):
        return None

    spec = h[len("bytes="):]

    # If no ranges specified, unsatisfiable
    if not spec:
        return None

    parts = [p.strip() for p in spec.split(",")]
    result = []

    for part in parts:
        if not part:
            continue  # skip empty parts from stray commas

        # Suffix-byte-range-spec: ends with a digit (e.g., -500)
        if part.startswith("-"):
            # Suffix byte range: last N bytes
            try:
                n = int(part[1:])
            except ValueError:
                return None
            if n <= 0:
                continue  # invalid suffix, drop
            if n >= size:
                # Suffix length larger than resource -> whole resource
                result.append((0, size - 1))
            else:
                start = size - n
                end = size - 1
                result.append((start, end))
            continue

        # If part ends with a dash, it's a range-start-only (e.g., "500-")
        if part.endswith("-"):
            try:
                start_str = part[:-1]
                start = int(start_str)
            except ValueError:
                return None
            if start < 0:
                continue  # negative start is unsatisfiable, drop
            if start >= size:
                # start at or past size -> unsatisfiable, drop
                continue
            result.append((start, size - 1))
            continue

        # General case: "start-end"
        dash_idx = part.find("-")
        if dash_idx == -1:
            # Single number without dash – treat as a range-start-only? 
            # RFC says this is invalid for byte-range-spec, but we drop it.
            continue

        start_str = part[:dash_idx]
        end_str = part[dash_idx + 1:]

        try:
            start = int(start_str)
            end = int(end_str) if end_str else None
        except ValueError:
            return None

        # Negative start in a normal range is unsatisfiable
        if start < 0:
            continue

        # If end is omitted, it runs to the end of the resource
        if end is None:
            if start >= size:
                continue  # unsatisfiable
            result.append((start, size - 1))
            continue

        # Both start and end present
        if start > end:
            continue  # malformed range, drop

        if start >= size:
            continue  # start at or past size -> unsatisfiable

        # Clamp end to the last byte
        if end >= size:
            end = size - 1

        result.append((start, end))

    # If every range was dropped, return None
    if not result:
        return None

    return result

