def damerau(a: str, b: str) -> int:
    n = len(a)
    m = len(b)

    # dp[i][j] stores distance between a[:i] and b[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    # last occurrence of each character in a and b (1-indexed)
    last_a = {}
    last_b = {}

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1

            # standard Levenshtein operations
            dp[i][j] = min(
                dp[i - 1][j] + 1,      # deletion
                dp[i][j - 1] + 1,      # insertion
                dp[i - 1][j - 1] + cost  # substitution / match
            )

            # unrestricted transposition of adjacent characters
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 2][j - 2] + 1)

            # track last positions for potential future transpositions
            if a[i - 1] in last_b:
                k = last_a[a[i - 1]]
                if k is not None and j > k + 1:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j - 2] + 1)
            if b[j - 1] in last_a:
                l = last_b[b[j - 1]]
                if l is not None and i > l + 1:
                    dp[i][j] = min(dp[i][j], dp[i - 2][j - 1] + 1)

        last_a[a[i - 1]] = i
    for j in range(1, m + 1):
        if b[j - 1] in last_a:
            pass  # last positions already recorded during the row loop

    return dp[n][m]
