class LFUCache:

    def __init__(self, capacity: int):
        self.capacity = capacity
        if capacity == 0:
            self.min_freq = 0
            self.key_val = {}
            self.key_freq = {}
            self.freq_map = {}
            return
        self.min_freq = 0
        self.key_val = {}
        self.key_freq = {}
        # freq -> OrderedDict of (key, value) in access order
        self.freq_map = {}

    def _update(self, key: int, value: int = None):
        """Move key to next frequency bucket. If value given, update the value."""
        freq = self.key_freq[key]
        # remove from current freq bucket
        od = self.freq_map[freq]
        del od[key]
        if not od:
            del self.freq_map[freq]
            if self.min_freq == freq:
                self.min_freq += 1

        # add to next frequency bucket
        nf = freq + 1
        self.key_freq[key] = nf
        if nf not in self.freq_map:
            from collections import OrderedDict
            self.freq_map[nf] = OrderedDict()
        od_nf = self.freq_map[nf]
        od_nf[key] = value if value is not None else self.key_val[key]
        # ensure the key's value is up to date in key_val
        if value is not None:
            self.key_val[key] = value

    def get(self, key: int) -> int:
        if self.capacity == 0 or key not in self.key_val:
            return -1
        self._update(key)
        return self.key_val[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.key_val:
            self.key_val[key] = value
            self._update(key, value)
            return

        # evict if at capacity
        if len(self.key_val) >= self.capacity:
            # evict from min_freq bucket the least recently used (first item)
            od_min = self.freq_map[self.min_freq]
            ev_key, _ = od_min.popitem(last=False)
            del self.key_val[ev_key]
            del self.key_freq[ev_key]

        # insert new key
        self.key_val[key] = value
        self.key_freq[key] = 1
        if 1 not in self.freq_map:
            from collections import OrderedDict
            self.freq_map[1] = OrderedDict()
        od_1 = self.freq_map[1]
        od_1[key] = value
        self.min_freq = 1

