import bisect

def lis_length(a):
    """Return length of longest strictly increasing subsequence in O(n log n)."""
    tails = []
    for x in a:
        # Find position to replace (first element >= x)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

