import heapq

def window_medians(a, k):
    n = len(a)
    if k > n or k <= 0:
        return []

    # max-heap for the lower half (store negatives)
    lo = []          # max-heap (negated values)
    # min-heap for the upper half
    hi = []          # min-heap

    # Helper to rebalance heaps so that len(lo) == len(hi) or len(lo) == len(hi) + 1
    def balance():
        # ensure lo[0] <= hi[0] (i.e. max of lower <= min of upper)
        if lo and hi and -lo[0] > hi[0]:
            v = -heapq.heappop(lo)
            heapq.heappush(hi, v)
        # size invariant
        if len(lo) > len(hi) + 1:
            v = -heapq.heappop(lo)
            heapq.heappush(hi, v)
        elif len(hi) > len(lo):
            v = heapq.heappop(hi)
            heapq.heappush(lo, -v)

    # Insert a value and rebalance
    def add(val):
        if not lo or val <= -lo[0]:
            heapq.heappush(lo, -val)
        else:
            heapq.heappush(hi, val)
        balance()

    # Remove a value from the heaps (lazy deletion using a counter)
    removed = {}   # value -> count to be ignored
    def purge():
        while lo and removed.get(-lo[0], 0):
            v = -heapq.heappop(lo)
            removed[v] -= 1
            if removed[v] == 0:
                del removed[v]
        while hi and removed.get(hi[0], 0):
            v = heapq.heappop(hi)
            removed[v] -= 1
            if removed[v] == 0:
                del removed[v]

    def remove(val):
        # mark for lazy deletion
        removed[val] = removed.get(val, 0) + 1
        purge()

    # Initialise first window
    for i in range(k):
        add(a[i])

    medians = []
    # Compute median for current window
    if k % 2 == 1:
        medians.append(float(-lo[0]))
    else:
        medians.append((-lo[0] + hi[0]) / 2.0)

    # Slide the window
    for i in range(k, n):
        # element leaving the window
        remove(a[i - k])
        # element entering the window
        add(a[i])

        if k % 2 == 1:
            medians.append(float(-lo[0]))
        else:
            medians.append((-lo[0] + hi[0]) / 2.0)

    return medians

