def subtract(base, cuts):
    # Normalize each list: merge overlapping/touching intervals and sort them.
    def normalize(intervals):
        if not intervals:
            return []
        # Sort by start, then end
        intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
        merged = []
        for s, e in intervals:
            if not merged or s > merged[-1][1]:
                merged.append([s, e])
            else:
                # Overlap or touch -> merge
                if e > merged[-1][1]:
                    merged[-1][1] = e
        return merged

    base_n = normalize(base)
    cuts_n = normalize(cuts)

    i, j = 0, 0
    result = []

    while i < len(base_n) and j < len(cuts_n):
        b_start, b_end = base_n[i]
        c_start, c_end = cuts_n[j]

        # No overlap
        if b_end <= c_start:
            i += 1
        elif c_end <= b_start:
            j += 1
        else:
            # Overlap exists
            # Part before the cut
            if b_start < c_start:
                result.append([b_start, min(b_end, c_start)])
            # Part after the cut
            if b_end > c_end:
                # Move cuts forward and keep remaining base part for next iteration
                j += 1
                # Adjust base start for the next comparison
                base_n[i][0] = c_end
                continue
            else:
                i += 1
                j += 1

    # Append any remaining base intervals
    while i < len(base_n):
        result.append(base_n[i])
        i += 1

    # Merge adjacent/touching intervals in the result
    if not result:
        return []

    merged_result = [list(result[0])]
    for s, e in result[1:]:
        last_s, last_e = merged_result[-1]
        if s <= last_e:          # touch or overlap -> merge
            if e > last_e:
                merged_result[-1][1] = e
        else:
            merged_result.append([s, e])

    return merged_result
