def deep_copy(obj):
    """Return a deep copy of obj preserving sharing graph and cycles."""
    # Immutable scalars: return as‑is
    if isinstance(obj, (str, int, float, bool)) or obj is None:
        return obj

    # Lists
    if isinstance(obj, list):
        # First pass: create empty copies and register mapping
        copy = []
        memo[id(obj)] = copy
        # Second pass: fill in the copies recursively
        for item in obj:
            copy.append(deep_copy(item))
        return copy

    # Tuples (including heterogeneous tuples)
    if isinstance(obj, tuple):
        # Create a placeholder list first so recursive calls can resolve it
        copy_list = []
        memo[id(obj)] = copy_list
        for item in obj:
            copy_list.append(deep_copy(item))
        # Convert the filled list back to a tuple
        return tuple(copy_list)

    # Dictionaries
    if isinstance(obj, dict):
        copy = {}
        memo[id(obj)] = copy
        for key, value in obj.items():
            copy[deep_copy(key] = deep_copy(value)
        return copy

    # Sets
    if isinstance(obj, set):
        copy = set()
        memo[id(obj)] = copy
        for item in obj:
            copy.add(deep_copy(item))
        return copy

    # Fallback for any other object type (treat as immutable scalar)
    return obj


# Global memo dictionary that persists across the recursion
memo = {}

