def to_base(n: int, alphabet: str) -> str:
    """Convert an integer to its representation in an arbitrary base given by `alphabet`.

    The alphabet string defines the digits from lowest value (index 0) to highest.
    Zero is represented by the first character of the alphabet. Negative numbers
    are prefixed with '-'.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must contain distinct characters")

    base = len(alphabet)
    digit_map = {ch: i for i, ch in enumerate(alphabet)}

    if n == 0:
        return alphabet[0]

    neg = n < 0
    if neg:
        n = -n

    digits = []
    while n > 0:
        n, rem = divmod(n, base)
        digits.append(alphabet[rem])

    if neg:
        digits.append('-')

    return ''.join(reversed(digits))


def from_base(s: str, alphabet: str) -> int:
    """Convert a string representation in an arbitrary base given by `alphabet` to an integer.

    The alphabet string defines the digits from lowest value (index 0) to highest.
    Raises ValueError on an empty string or on a character not present in the alphabet.
    """
    if not s:
        raise ValueError("Input string must not be empty")
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must contain distinct characters")

    base = len(alphabet)
    digit_map = {ch: i for i, ch in enumerate(alphabet)}

    # Strip leading minus sign if present
    neg = False
    if s[0] == '-':
        neg = True
        s = s[1:]
        if not s:
            raise ValueError("Empty string after removing sign")

    # Validate all characters
    for ch in s:
        if ch not in digit_map:
            raise ValueError(f"Character {ch!r} not in alphabet")

    # Convert to integer
    value = 0
    for ch in s:
        value = value * base + digit_map[ch]

    if neg:
        value = -value

    return value


