import heapq

def topo_lex(graph):
    # Collect all nodes (keys and successors)
    all_nodes = set()
    for u, succ in graph.items():
        all_nodes.add(u)
        for v in succ:
            all_nodes.add(v)

    if not all_nodes:
        return []

    # Compute indegrees
    indeg = {node: 0 for node in all_nodes}
    for u, succ in graph.items():
        for v in succ:
            indeg[v] += 1

    # Min-heap of nodes with indegree 0
    heap = [node for node in all_nodes if indeg[node] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        # Successors of u (may be missing from graph dict)
        succ = graph.get(u, [])
        for v in succ:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    if len(order) != len(all_nodes):
        return None
    return order

