function pLimit(n) {
  let active = 0;
  const queue = [];

  function run() {
    if (active >= n || !queue.length) return;

    const { fn, resolve, reject } = queue.shift();
    active++;
    fn()
      .then((result) => {
        resolve(result);
      })
      .catch((error) => {
        reject(error);
      })
      .finally(() => {
        active--;
        run();
      });
  }

  return function (fn) {
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      run();
    });
  };
}

