class Emitter {
  constructor() {
    this._listeners = {};
  }

  on(event, fn) {
    if (!this._listeners[event]) {
      this._listeners[event] = [];
    }
    const index = this._listeners[event].length;
    this._listeners[event].push(fn);
    const self = this;
    return function unsubscribe() {
      const listeners = self._listeners[event];
      if (listeners) {
        const idx = listeners.indexOf(fn);
        if (idx !== -1) {
          listeners.splice(idx, 1);
        }
      }
    };
  }

  once(event, fn) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      fn.apply(this, args);
    };
    return this.on(event, wrapper);
  }

  off(event, fn) {
    const listeners = this._listeners[event];
    if (listeners) {
      const idx = listeners.indexOf(fn);
      if (idx !== -1) {
        listeners.splice(idx, 1);
      }
    }
  }

  emit(event, ...args) {
    const listeners = this._listeners[event];
    if (!listeners || listeners.length === 0) {
      return 0;
    }

    // Collect errors and track invoked count
    const errors = [];
    let invokedCount = 0;

    // Snapshot current listeners to protect against additions/removals during emit
    const snapshot = listeners.slice();

    for (const fn of snapshot) {
      try {
        fn.apply(this, args);
        invokedCount++;
      } catch (e) {
        if (!errors.length) {
          errors.push(e);
        }
      }
    }

    // Rethrow the first error if any
    if (errors.length > 0) {
      throw errors[0];
    }

    return invokedCount;
  }
}

