async function* chunkAsync(source, size) {
  const iterator = source[Symbol.asyncIterator]();
  let done = false;
  let buffer = [];

  while (!done || buffer.length > 0) {
    if (buffer.length < size) {
      const { value, done: nextDone } = await iterator.next();
      if (nextDone) {
        done = true;
        // Yield remaining items as a final short chunk
        if (buffer.length > 0) {
          yield buffer;
        }
        break;
      }
      buffer.push(value);
    }

    // Yield up to `size` items from the buffer
    const chunk = buffer.splice(0, size);
    if (chunk.length > 0) {
      yield chunk;
    }
  }

  await iterator.return();
}

