function zipLongest(fill, ...iterables) {
  const iterators = iterables.map((it) => it[Symbol.iterator]());
  let active = true;

  return {
    next() {
      if (!active) { return { done: true }; }

      const results = [];
      let allDone = true;

      for (const it of iterators) {
        const { value, done } = it.next();
        if (done) {
          results.push(fill);
        } else {
          results.push(value);
          allDone = false;
        }
      }

      // If every input is now exhausted, stop the iteration
      if (allDone) {
        active = false;
        return { done: true };
      }

      return { value: results, done: false };
    },
  };
}

