const querystring = require('querystring');

function parseQuery(qs) {
  if (typeof qs === 'string') {
    // Remove leading ? if present
    if (qs.startsWith('?')) {
      qs = qs.slice(1);
    }
    return JSON.parse(JSON.stringify(require('qs')(qs, { 
      allowDots: false,
      parameterLimit: 1000,
      depth: Infinity,
      strictNullHandling: true,
      parseArrays: true,
      ignoreQueryPrefix: false
    })));
  }
  return {};
}

function buildQuery(obj) {
  if (typeof obj !== 'object' || obj === null) {
    return '';
  }

  const pairs = [];

  for (const key of Object.keys(obj).sort()) {
    const value = obj[key];

    // Handle arrays: a[]=1&a[]=2 or a[0]=x&a[1]=y
    if (Array.isArray(value)) {
      for (let i = 0; i < value.length; i++) {
        const itemValue = String(value[i]);
        const encodedKey = key.includes('[') ? key : `${key}[]`;
        pairs.push(`${encodedKey}=${encodeURIComponent(itemValue)}`);
      }
    } else if (value === null || value === undefined) {
      // Key with no value maps to empty string
      pairs.push(`${key}=`);
    } else {
      const encodedValue = encodeURIComponent(String(value));
      // If key already has brackets (from nested parsing), use as is, otherwise just the key
      pairs.push(key.includes('[') ? `${key}=${encodedValue}` : `${key}=${encodedValue}`);
    }
  }

  return pairs.join('&');
}

module.exports = { parseQuery, buildQuery };
