function createStore(reducer, initial) {
  let state = reducer(initial, { type: '@@INIT' });
  const listeners = [];

  return {
    getState() {
      return state;
    },

    dispatch(action) {
      if (action.type === undefined && typeof action !== 'object') {
        throw new Error('Actions must be plain objects. Use custom middleware for async.');
      }

      // Check if dispatching from inside a reducer
      try {
        state = reducer(state, action);
      } catch (e) {
        if (e.message === 'Dispatching from inside reducer is not allowed') {
          throw e;
        }
        // If it's a different error, rethrow
        throw e;
      }

      const listenersCopy = listeners.slice();
      for (let i = 0; i < listenersCopy.length; i++) {
        listenersCopy[i]();
      }
    },

    subscribe(fn) {
      listeners.push(fn);
      return () => {
        const index = listeners.indexOf(fn);
        if (index > -1) {
          listeners.splice(index, 1);
        }
      };
    }
  };
}

module.exports = createStore;
