function toposortTasks(tasks) {
  const visited = new Set();
  const visiting = new Set();
  const order = [];
  const errors = [];

  function visit(name) {
    if (visiting.has(name)) {
      throw new Error('cycle detected');
    }
    if (visited.has(name)) return;
    if (!tasks[name]) {
      errors.push(new Error(`unknown task: ${name}`));
      return;
    }
    visiting.add(name);
    const deps = tasks[name].deps || [];
    for (const dep of deps) {
      if (!tasks[dep]) {
        errors.push(new Error(`missing dependency: ${dep}`));
        continue;
      }
      visit(dep);
      if (errors.length > 0) break;
    }
    if (errors.length === 0) order.push(name);
    visiting.delete(name);
    visited.add(name);
  }

  for (const name of Object.keys(tasks)) {
    try {
      visit(name);
    } catch (e) {
      errors.push(e);
    }
  }

  if (errors.length > 0) {
    return Promise.reject(errors[0]);
  }

  const results = {};
  let pending = order.length;
  let hasRejected = false;

  function complete(name, value) {
    results[name] = value;
    pending--;
    if (pending === 0) {
      if (hasRejected) {
        return Promise.reject(new Error('task rejected'));
      }
      return Promise.resolve(results);
    }
  }

  function reject(err) {
    hasRejected = true;
    // Allow in-flight tasks to finish but mark rejection
    pending = 0;
  }

  for (const name of order) {
    const deps = tasks[name].deps || [];
    const depValues = {};
    for (const dep of deps) {
      depValues[dep] = results[dep];
    }
    tasks[name].run(depValues).then(
      (value) => complete(name, value),
      (err) => {
        // If this task rejects, we record it but allow others to finish
        if (!hasRejected) {
          reject(err);
        }
      }
    );
  }

  return Promise.resolve(results);
}

module.exports = toposortTasks;
