export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<keyof E, Array<(payload: E[keyof E]) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    const list = this.handlers.get(k) ?? [];
    list.push(fn);
    this.handlers.set(k, list);
    return () => {
      const arr = this.handlers.get(k);
      if (arr) {
        const idx = arr.indexOf(fn);
        if (idx !== -1) arr.splice(idx, 1);
      }
    };
  }

  emit<K extends keyof E>(k: K, payload: E[K]): void {
    const list = this.handlers.get(k);
    if (list) {
      for (const fn of list) fn(payload);
    }
  }
}
