type OptionalKeys<T> = { [K in keyof T as NonNullable<T[K]> extends T[K] ? never : true]: K };

export function Builder<Config extends Record<string, unknown>>(): {
  set<K extends keyof Config>(key: K, value: Config[K]): Builder<Config>;
  build(): Config;
} {
  let built = false;

  return {
    set(key, value) {
      if (built) throw new Error("Already built");
      // @ts-expect-error - runtime check for unknown keys
      if (!(key in this)) throw new Error("Unknown key");
      // @ts-expect-error - runtime check for type mismatch  
      if (typeof value !== typeof (this as any)[key]) throw new Error("Type mismatch");
      ;(this as any)[key] = value;
      return this;
    },
    build() {
      if (built) throw new Error("Already built");
      built = true;
      return {} as Config;
    }
  };
}
