type DeepAwaited<T> = T extends Promise<infer U>
  ? U extends Promise<any>
    ? DeepAwaited<U>
    : U extends (...args: any[]) => any
      ? T
      : DeepAwaited<U>
  : T extends readonly (infer V)[]
  ? DeepAwaited<V>[]
  : T extends { [K in keyof V]: V[K] }
    ? { [K in keyof V]: DeepAwaited<V[K]> }
    : T;

function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value instanceof Promise) {
    return value.then((resolved) => deepAwait(resolved)) as unknown as Promise<DeepAwaited<T>>;
  }
  if (Array.isArray(value)) {
    return Promise.all(value.map(deepAwait)) as unknown as Promise<DeepAwaited<T>>;
  }
  if (value !== null && typeof value === "object") {
    const result: Record<string, any> = {};
    for (const key of Object.keys(value)) {
      result[key] = deepAwait((value as Record<string, unknown>)[key]);
    }
    return Promise.all(Object.values(result)).then(() => result as DeepAwaited<T>);
  }
  return Promise.resolve(value) as unknown as Promise<DeepAwaited<T>>;
}

export { DeepAwaited, deepAwait };
