export function defineRoutes(
  routes: Record<string, string>
): Record<
  keyof typeof routes,
  // Extract params from path template and map to an object of strings
  (params?: { [K in Extract<Parameters<typeof routes[K]>, never>]: string }) => string
> {
  const routeMap = new Map<string, string[]>();

  for (const [name, path] of Object.entries(routes)) {
    const params: string[] = [];
    const regexStr = path.replace(/:([^/]+)/g, (_, key) => {
      params.push(key);
      return '([^/]+)';
    });
    routeMap.set(name, [regexStr, ...params]);
  }

  const result: Record<string, (...args: unknown[]) => string> = {} as any;

  for (const [name, path] of Object.entries(routes)) {
    const regexStr = path.replace(/:([^/]+)/g, '([^/]+)');
    const re = new RegExp(`^${regexStr}$`);

    result[name] = function (paramsObj?: { [k: string]: string }): string {
      if (paramsObj === undefined) {
        // No params in path template
        return path;
      }

      const matches = path.match(re);
      if (!matches) {
        throw new Error(`Path does not match template: ${path}`);
      }

      // Build result by replacing placeholders with provided values
      let resultPath = path;
      for (let i = 1; i < matches.length; i++) {
        const key = (path.match(/:([^/]+)/g) || [])[i - 1]?.replace(':', '') ?? `param${i}`;
        resultPath = resultPath.replace(`:${key}`, matches[i]);
      }
      return resultPath;
    };
  }

  return result as Record<keyof typeof routes, (...args: unknown[]) => string>;
}
